"""
**最初から持っているカタカナ語**（うにさんの指定・2026-08-11）。

これまで「カタカナの直し先はメモのどこかに正しく書いてある語だけ」
という作りだった。そのため**入れたばかりのアプリではカタカナ語の
補正が一度も効かない**（プセネタリウム も とせらっぐ も直らない）。
初期状態で測って分かったいちばん大きな穴（項目48-AW）。

うにさんの指示で方針を変えた:

  変えた前  外部の辞書もモデルも持ち込まない
  変えた後  **単語リストは持ち込む。学習済みモデルと通信は持ち込まない**

単語リストは中身が読めて検証できるので、「安全性がコードで
確かめられる」という軸と矛盾しない。

作り方は `seed_katakana_build.py`（開発時のみ）。
IPAdic の一般名詞のうち、**3文字以上のカタカナだけ**で、
生起コストが 8000 未満（＝珍しすぎないもの）を採った。
固有名詞は入れない（人名・地名は誤変換先になりやすく、
`looks_like_real_word` が固有名詞を実在の根拠にしないのと同じ理由）。

**COMMON_WORDS**（2026-08-12・項目48-BI）は、**ふつうに使う語**
（UniDic 基準で馴染みのずれが 0）。5文字以下の短い語をひらがなから
カタカナへ寄せてよいのは、この一覧に入っているときだけ。
`すくろーる → スクロール` は通り、`しゅぷーる → シュプール` は
通らない（実機のメモ tab0 493行。前後は「ぎょえん」「うにゅーん」
で、外来語のつもりではない）。

**表そのものではなく、線引きの結果だけをここに持つ。**
`familiarity.json` は exe に同梱していない（build.yml は
保護対象で触れない）ので、そちらに頼ると**黙って効かなくなる**
（項目48-AF の教訓）。

**AMBIGUOUS_WORDS**（2026-08-12・項目48-BH）は、そのうち
**同じ読みでカタカナ以外の表記も辞書にある**語。
`かたつむり`（蝸牛）・`さくら`（桜）・`ぼたん`（牡丹）など。
**ひらがなで書かれたものをカタカナへ寄せてよいのは、
この一覧に入っていない語だけ**（入っていたら、その人は
わざとひらがな／漢字で書いているかもしれない）。
"""

